// Per-backup Data Encryption Key (DEK) generation, wrapping, and
// unwrapping. The DEK is wrapped with the master key using AES-256-GCM
// and stored as a self-contained 60-byte blob: IV (12) + ciphertext
// (32) + GCM tag (16).

import { createCipheriv, createDecipheriv, createHash, randomBytes } from 'node:crypto';

export const DEK_SIZE = 32;
export const MASTER_KEY_SIZE = 32;
export const WRAPPED_DEK_SIZE = 60; // 12 + 32 + 16

export function generateDek(): Buffer {
  return randomBytes(DEK_SIZE);
}

export function wrapDek(dek: Buffer, masterKey: Buffer): Buffer {
  if (dek.length !== DEK_SIZE) throw new Error(`DEK must be ${DEK_SIZE} bytes (got ${dek.length})`);
  if (masterKey.length !== MASTER_KEY_SIZE) throw new Error(`master key must be ${MASTER_KEY_SIZE} bytes (got ${masterKey.length})`);

  const iv = randomBytes(12);
  const cipher = createCipheriv('aes-256-gcm', masterKey, iv);
  const ciphertext = Buffer.concat([cipher.update(dek), cipher.final()]);
  const tag = cipher.getAuthTag();

  const wrapped = Buffer.alloc(WRAPPED_DEK_SIZE);
  iv.copy(wrapped, 0);
  ciphertext.copy(wrapped, 12);
  tag.copy(wrapped, 44);
  return wrapped;
}

export function unwrapDek(wrapped: Buffer, masterKey: Buffer): Buffer {
  if (wrapped.length !== WRAPPED_DEK_SIZE) {
    throw new Error(`wrapped DEK must be ${WRAPPED_DEK_SIZE} bytes (got ${wrapped.length})`);
  }
  if (masterKey.length !== MASTER_KEY_SIZE) {
    throw new Error(`master key must be ${MASTER_KEY_SIZE} bytes`);
  }
  const iv = wrapped.subarray(0, 12);
  const ciphertext = wrapped.subarray(12, 44);
  const tag = wrapped.subarray(44, 60);
  const decipher = createDecipheriv('aes-256-gcm', masterKey, iv);
  decipher.setAuthTag(tag);
  let plaintext: Buffer | undefined;
  let final: Buffer | undefined;
  try {
    plaintext = decipher.update(ciphertext);
    final = decipher.final();
    // Transfer only the separate returned DEK; both helper-owned plaintext
    // temporaries must be cleared even if authentication or concatenation fails.
    return Buffer.concat([plaintext, final]);
  } finally {
    plaintext?.fill(0);
    final?.fill(0);
  }
}

/**
 * SHA-256(key)[:16] as hex. Used to identify which master-key version
 * wrapped a given DEK so the DR CLI can fail loudly on wrong-key
 * attempts instead of returning corrupt plaintext.
 */
export function computeKeyFingerprint(key: Buffer): string {
  return createHash('sha256').update(key).digest('hex').slice(0, 32);
}

export function wrapDekHex(dek: Buffer, masterKey: Buffer): string {
  return wrapDek(dek, masterKey).toString('hex');
}
export function unwrapDekHex(wrappedHex: string, masterKey: Buffer): Buffer {
  if (!/^[0-9a-f]+$/i.test(wrappedHex)) throw new Error('wrappedHex must be a hex string');
  if (wrappedHex.length < 120) throw new Error('wrappedHex too short: expected 60 bytes');
  if (wrappedHex.length !== 120) throw new Error('wrapped hex envelope must be 60 bytes');
  return unwrapDek(Buffer.from(wrappedHex, 'hex'), masterKey);
}
